import assert from 'node:assert/strict';import {chromium} from 'playwright-core'
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist','--use-angle=metal']})
try{const page=await browser.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:5277/qa/exo-avatar-pose-physical-bridge-20261102.html',{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>Array.isArray(window.__exoPosePhysicalResults),null,{timeout:60000});const result=await page.evaluate(()=>window.__exoPosePhysicalResults);console.log('EXO_POSE_BRIDGE',JSON.stringify({result,errors},null,2));assert.equal(result.length,3);assert.deepEqual(errors,[]);for(const row of result){assert.ok(!row.error,row.error);assert.equal(row.animationTracks,489);assert.equal(row.within5mm,true,JSON.stringify(row))}}finally{await browser.close()}
